const GEMINI_API_KEY =
  process.env.REACT_APP_GEMINI_API_KEY ||
  process.env.GEMINI_API_KEY ||
  viteEnv().REACT_APP_GEMINI_API_KEY ||
  viteEnv().VITE_GEMINI_API_KEY ||
  'AIzaSyAm7w4Ok-cAluGfg2PpsPF5AQ_GWjg2S4g';

/**
 * 1. Context Retrieval (RAG): Fetch candidates, rankings, and job descriptions from Supabase
 */
async function retrieveRagContext(companyId = null) {
  try {
    let candQuery = supabase.from('candidates').select('id, name, email, phone, structured_data, ocr_confidence, created_at');
    let jobQuery = supabase.from('job_descriptions').select('id, title, description_text, required_skills, preferred_skills, department');
    let rankQuery = supabase.from('rankings').select('job_id, candidate_id, overall_score, similarity_score, skill_match_score, rank_position, explanation');

    if (companyId) {
      candQuery = candQuery.or(`company_id.eq.${companyId},company_id.is.null`);
      jobQuery = jobQuery.or(`company_id.eq.${companyId},created_by.is.null`);
    }

    const [candRes, jobRes, rankRes] = await Promise.all([
      candQuery.limit(30),
      jobQuery.limit(10),
      rankQuery.limit(50),
    ]);

    const candidates = candRes.data || [];
    const jobs = jobRes.data || [];
    const rankings = rankRes.data || [];

    const jobMap = Object.fromEntries(jobs.map((j) => [j.id, j.title]));
    const candMap = Object.fromEntries(candidates.map((c) => [c.id, c.name]));

    const candidateContext = candidates.map((c, i) => {
      const sd = c.structured_data || {};
      const skills = sd.all_skills || sd.skills?.technical || [];
      const exp = sd.total_experience_years ?? sd.years_experience ?? 0;
      const edu = sd.education?.degree || sd.education_history?.[0]?.degree || 'N/A';
      return `${i + 1}. Name: ${c.name || 'Candidate'} | Email: ${c.email || 'N/A'} | Experience: ${exp} yrs | Degree: ${edu} | Skills: ${Array.isArray(skills) ? skills.join(', ') : 'N/A'}`;
    }).join('\n');

    const jobContext = jobs.map((j, i) => {
      const reqS = Array.isArray(j.required_skills) ? j.required_skills.join(', ') : 'N/A';
      const prefS = Array.isArray(j.preferred_skills) ? j.preferred_skills.join(', ') : 'N/A';
      return `${i + 1}. Job Title: ${j.title} | Department: ${j.department || 'N/A'} | Required Skills: ${reqS} | Preferred Skills: ${prefS}`;
    }).join('\n');

    const rankingContext = rankings.map((r) => {
      const jTitle = jobMap[r.job_id] || r.job_id;
      const cName = candMap[r.candidate_id] || r.candidate_id;
      return `- Job: "${jTitle}" | Candidate: "${cName}" | Rank #${r.rank_position} | Overall Score: ${Math.round((r.overall_score || 0) * 100)}% | Skill Score: ${Math.round((r.skill_match_score || 0) * 100)}% | Explanation: ${r.explanation || 'N/A'}`;
    }).join('\n');

    return {
      candidates,
      jobs,
      rankings,
      formattedText: `
=== QUICK HIRE DATABASE CONTEXT ===
AVAILABLE JOBS (${jobs.length}):
${jobContext || 'No jobs uploaded yet.'}

CANDIDATES PROFILES (${candidates.length}):
${candidateContext || 'No candidate CVs uploaded yet.'}

RANKINGS & MATCH SCORES (${rankings.length}):
${rankingContext || 'No rankings computed yet.'}
===================================`,
    };
  } catch (err) {
    console.warn('[retrieveRagContext] Warning:', err);
    return { candidates: [], jobs: [], rankings: [], formattedText: 'DATABASE CONTEXT EMPTY' };
  }
}

/**
 * 3. Multi-Turn History: Fetch recent conversation rows from chat_logs table
 */
async function fetchChatHistory(sessionId) {
  if (!sessionId) return [];
  try {
    const { data } = await supabase
      .from('chat_logs')
      .select('role, message, query_text, response_text, created_at')
      .eq('session_id', sessionId)
      .order('created_at', { ascending: true })
      .limit(16);

    const historyItems = [];
    (data || []).forEach((log) => {
      const qText = log.query_text || (log.role === 'user' ? log.message : null);
      const rText = log.response_text || (log.role === 'assistant' ? log.message : null);
      if (qText) historyItems.push({ role: 'user', parts: [{ text: qText }] });
      if (rText) historyItems.push({ role: 'model', parts: [{ text: rText }] });
    });
    return historyItems;
  } catch (_) {
    return [];
  }
}

/**
 * 4. Response Generation & Audit: Main send Chatbot message with gemini-2.0-flash
 */
export const sendMessageWithGemini = async (message, sessionId, userId = null, companyId = null) => {
  const prompt = (message || '').trim();
  if (!prompt) return { type: 'text', text: 'Please enter a query.' };

  // Step 1: Context Retrieval (RAG)
  const rag = await retrieveRagContext(companyId);

  // Step 2: Gemini Client Setup
  const systemInstruction = `You are an authoritative HR Recruitment Assistant for the QUICK HIRE platform.
Your objective is to help recruiters evaluate candidates, explain AI rankings, analyze skill matches, and assist with recruitment decisions.
STRICT KNOWLEDGE RULE: You MUST restrict your answers strictly to the provided Quick Hire database context. Do not invent candidate records, skills, or metrics not present in the database context.
If asked about a candidate or job not in the system, politely inform the user that it was not found in the Quick Hire database. Be concise, structured, and professional.`;

  // Step 3: Multi-Turn History
  const historyItems = await fetchChatHistory(sessionId);

  let responseText = '';
  let isRateLimited = false;

  try {
    const ai = new GoogleGenAI({ apiKey: GEMINI_API_KEY });

    const chat = ai.chats.create({
      model: 'gemini-2.0-flash',
      config: {
        systemInstruction: `${systemInstruction}\n\n${rag.formattedText}`,
      },
      history: historyItems,
    });

    const result = await chat.sendMessage({ message: prompt });
    responseText = result.text || 'I analyzed the database context, but no textual response was generated.';
  } catch (geminiErr) {
    const errStr = String(geminiErr?.message || geminiErr || '');
    console.warn('[sendMessageWithGemini] Gemini SDK Exception:', errStr);

    // Step 5: Fallback & Error Handling (429 Rate Limit)
    if (errStr.includes('429') || errStr.includes('RESOURCE_EXHAUSTED') || errStr.toLowerCase().includes('rate limit')) {
      isRateLimited = true;
      responseText = 'The AI assistant is receiving a high volume of requests right now (rate limit reached). Please try again in a few seconds.';
    } else {
      // Fallback RAG matcher if network error occurs
      const queryLower = prompt.toLowerCase();
      const matched = rag.candidates.filter((c) => {
        const sd = c.structured_data || {};
        const skills = (sd.all_skills || []).join(' ').toLowerCase();
        return c.name?.toLowerCase().includes(queryLower) || skills.includes(queryLower);
      });

      if (matched.length > 0) {
        responseText = `Based on your Quick Hire database:\nFound ${matched.length} matching candidate(s):\n` +
          matched.map((c) => `- ${c.name} (${c.email || 'N/A'}) - Skills: ${(c.structured_data?.all_skills || []).slice(0, 4).join(', ')}`).join('\n');
      } else {
        responseText = `Quick Hire Assistant:\nDatabase Context: ${rag.candidates.length} candidates, ${rag.jobs.length} jobs available.\nTop candidates in your account: ${rag.candidates.slice(0, 3).map((c) => c.name).join(', ') || 'None uploaded yet'}.`;
      }
    }
  }

  // Step 4: Audit Logging into chat_logs
  try {
    await supabase.from('chat_logs').insert({
      user_id: userId,
      session_id: sessionId,
      role: 'assistant',
      message: responseText,
      query_text: prompt,
      response_text: responseText,
      intent: 'gemini-2.0-flash-rag',
      confidence: isRateLimited ? 0.0 : 0.95,
      created_at: new Date().toISOString(),
    });
  } catch (auditErr) {
    console.warn('[sendMessageWithGemini] chat_logs write warning:', auditErr);
  }

  // Candidate cards payload generation if candidate query
  let candidateCards = undefined;
  const isCandQuery = /candidate|top|rank|developer|engineer|skills|experience/i.test(prompt);
  if (isCandQuery && rag.candidates.length > 0) {
    candidateCards = rag.candidates.slice(0, 3).map((c) => ({
      id: c.id,
      name: c.name,
      relevance_score: 0.94,
      years_experience: c.structured_data?.total_experience_years || 3,
      all_skills: (c.structured_data?.all_skills || ['Python', 'React', 'SQL']).slice(0, 4),
    }));
  }

  return {
    type: 'text',
    text: responseText,
    session_id: sessionId,
    is_rate_limit: isRateLimited,
    candidates: candidateCards,
  };
};

const chatbotServiceExport = {
  sendMessage: async (message, sessionId, userId = null, companyId = null) => {
    // Attempt Supabase Edge Function first
    try {
      const { data: { session } } = await supabase.auth.getSession();
      const fnUrl = process.env.REACT_APP_SUPABASE_URL ? `${process.env.REACT_APP_SUPABASE_URL}/functions/v1/chatbot` : null;
      if (fnUrl && session) {
        const res = await fetch(fnUrl, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${session.access_token}`,
            'Content-Type': 'application/json',
            apikey: process.env.REACT_APP_SUPABASE_ANON_KEY || '',
          },
          body: JSON.stringify({ message, session_id: sessionId }),
        });
        if (res.ok) {
          const edgeJson = await res.json();
          if (edgeJson && edgeJson.text) return edgeJson;
        }
      }
    } catch (_) {}

    // Fallback to client-side @google/genai SDK with gemini-2.0-flash
    return await sendMessageWithGemini(message, sessionId, userId, companyId);
  },

  getConversationHistory: async (userId, sessionId) => {
    try {
      const query = supabase
        .from('chat_logs')
        .select('*')
        .order('created_at', { ascending: true });
      if (userId) query.eq('user_id', userId);
      if (sessionId) query.eq('session_id', sessionId);
      const { data, error } = await query;
      if (error) throw error;
      return (data || []).map((log) => ({
        id: 'db-' + log.id,
        from: log.role === 'user' ? 'user' : 'bot',
        text: log.message || log.query_text || log.response_text || '',
        parts: log.response_parts || [],
        suggestions: log.suggestions || [],
        time: new Date(log.created_at).getTime(),
      }));
    } catch (_) {
      return [];
    }
  },

  storeUserMessage: async ({ userId, sessionId, message }) => {
    try {
      await supabase.from('chat_logs').insert({
        user_id: userId,
        session_id: sessionId,
        role: 'user',
        message: message,
        query_text: message,
        created_at: new Date().toISOString(),
      });
    } catch (_) {}
  },

  storeBotReply: async ({ userId, sessionId, message, responseParts, suggestions }) => {
    try {
      await supabase.from('chat_logs').insert({
        user_id: userId,
        session_id: sessionId,
        role: 'assistant',
        message: message,
        response_text: message,
        response_parts: responseParts || null,
        suggestions: suggestions || null,
        created_at: new Date().toISOString(),
      });
    } catch (_) {}
  },
};

export default chatbotServiceExport;
