import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import CompanyLayout from '../components/CompanyLayout';
import { useUser } from '../context/UserContext';
import { companyService, jobService, adminService } from '../services/supabaseService';

const CompanyDashboard = () => {
  const { user } = useUser();
  const [recruiters, setRecruiters] = useState([]);
  const [jobs, setJobs] = useState([]);
  const [dashStats, setDashStats] = useState({ total_candidates: 0, recent_rankings: 0, total_jobs: 0 });
  const [approvals, setApprovals] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadAll = async () => {
    if (!user?.company_id) return;
    const companyId = user.company_id;
    const [r, j, ds, a] = await Promise.all([
      companyService.getRecruiters(companyId),
      jobService.getJobs(companyId),
      adminService.getDashboardStats(companyId),
      companyService.getShortlistApprovals(companyId),
    ]);
    setRecruiters(r);
    setJobs(j);
    setDashStats(ds);
    setApprovals(a.slice(0, 3));
  };

  useEffect(() => {
    const load = async () => {
      try {
        await loadAll();
      } finally {
        setLoading(false);
      }
    };
    if (user) load();
  }, [user]);

  const handleApproveAction = async (id, approved) => {
    try {
      await companyService.approveAction(id, approved);
      await loadAll();
    } catch (e) {
      console.error(e);
    }
  };

  if (loading) return <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '60vh' }}><div className="spinner spinner-lg"></div></div>;

  const activeRecruiters = recruiters.filter(r => r.status === 'active').length;
  const candidatesReviewed = recruiters.reduce((sum, r) => sum + (r.candidatesReviewed || 0), 0);
  const shortlisted = recruiters.reduce((sum, r) => sum + (r.shortlisted || 0), 0);
  const pendingApprovals = approvals.filter(a => a.status === 'pending').length;
  const recentRecruiters = recruiters.slice(0, 4);

  return (
    <CompanyLayout
      user={user}
      title="Company Overview"
      subtitle="Manage recruiters, monitor activity and approve shortlists."
      actions={
        <>
          <Link to="/company/recruiters" className="btn btn-outline-secondary btn-sm"><FontAwesomeIcon icon="users" style={{ marginRight: 6 }} /> Recruiters</Link>
          <Link to="/company/approvals" className="btn btn-primary btn-sm"><FontAwesomeIcon icon="clipboard-check" style={{ marginRight: 6 }} /> Approvals</Link>
        </>
      }
    >
      <div className="grid-4 mb-5">
        <div className="stats-card">
          <div className="stats-icon primary"><FontAwesomeIcon icon="users" /></div>
          <div className="stats-value">{activeRecruiters}</div>
          <div className="stats-label">Active Recruiters</div>
          <div className="stats-trend up">{recruiters.length} total team</div>
        </div>
        <div className="stats-card gold">
          <div className="stats-icon gold"><FontAwesomeIcon icon="chart-bar" /></div>
          <div className="stats-value">{candidatesReviewed}</div>
          <div className="stats-label">Candidates Reviewed</div>
          <div className="stats-trend up">{dashStats.total_candidates} total CVs</div>
        </div>
        <div className="stats-card success">
          <div className="stats-icon success"><FontAwesomeIcon icon="trophy" /></div>
          <div className="stats-value">{shortlisted}</div>
          <div className="stats-label">Shortlisted</div>
          <div className="stats-trend up">{dashStats.recent_rankings} rankings done</div>
        </div>
        <div className="stats-card warning">
          <div className="stats-icon warning"><FontAwesomeIcon icon="clipboard-check" /></div>
          <div className="stats-value">{pendingApprovals}</div>
          <div className="stats-label">Pending Approvals</div>
          <div className="stats-trend up">{dashStats.total_jobs} jobs posted</div>
        </div>
      </div>

      <div className="grid-2-1 mb-5">
        <div className="card">
          <div className="card-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span><FontAwesomeIcon icon="users" style={{ marginRight: 6 }} />Recent Recruiters</span>
            <Link to="/company/recruiters" style={{ fontSize: '0.78rem', color: 'var(--primary-mid)', fontWeight: 700 }}>View all →</Link>
          </div>
          <div className="card-body" style={{ padding: '0.5rem 0.25rem 0.25rem' }}>
            {recentRecruiters.length === 0 ? (
              <div style={{ padding: '1.5rem 1rem', textAlign: 'center', color: 'var(--text-light)', fontSize: '0.85rem' }}>
                No recruiters yet. Invite your team to get started.
              </div>
            ) : (
              recentRecruiters.map(r => (
                <div key={r.id} style={{ display: 'flex', alignItems: 'center', padding: '0.75rem 0.5rem', borderBottom: '1px solid var(--border-color)' }}>
                  <div className="avatar avatar-gold" style={{ marginRight: '0.75rem' }}>
                    {(r.name || 'R').split(' ').map(n => n[0]).join('').slice(0, 2)}
                  </div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <div style={{ fontWeight: 600, color: 'var(--primary-dark)', fontSize: '0.9rem' }}>{r.name}</div>
                      {r.status === 'active' && <span className="badge badge-success">Active</span>}
                      {r.status === 'invited' && <span className="badge badge-warning">Invited</span>}
                      {r.status === 'suspended' && <span className="badge badge-error">Suspended</span>}
                      {!['active', 'invited', 'suspended'].includes(r.status) && <span className="badge badge-secondary">{r.status}</span>}
                    </div>
                    <div style={{ fontSize: '0.78rem', color: 'var(--text-light)', marginTop: '0.1rem' }}>{r.email}</div>
                    <div style={{ fontSize: '0.72rem', color: 'var(--text-gray)', marginTop: '0.2rem' }}>
                      <FontAwesomeIcon icon="clipboard-list" style={{ marginRight: 4 }} />{r.candidatesReviewed || 0} reviewed · <FontAwesomeIcon icon="trophy" style={{ marginRight: 4 }} />{r.shortlisted || 0} shortlisted
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        <div className="card">
          <div className="card-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <span><FontAwesomeIcon icon="clipboard-check" style={{ marginRight: 6 }} />Pending Approvals</span>
            <Link to="/company/approvals" style={{ fontSize: '0.78rem', color: 'var(--primary-mid)', fontWeight: 700 }}>View all →</Link>
          </div>
          <div className="card-body" style={{ padding: '0.5rem 0.25rem 0.25rem' }}>
            {approvals.length === 0 ? (
              <div style={{ padding: '1.5rem 1rem', textAlign: 'center', color: 'var(--text-light)', fontSize: '0.85rem' }}>
                No pending approvals. All caught up!
              </div>
            ) : (
              approvals.map(a => (
                <div key={a.id} style={{ padding: '0.75rem 0.5rem', borderBottom: '1px solid var(--border-color)' }}>
                  <div style={{ fontWeight: 600, color: 'var(--primary-dark)', fontSize: '0.88rem' }}>{a.action}</div>
                  <div style={{ fontSize: '0.78rem', color: 'var(--text-light)', marginTop: '0.15rem' }}>
                    <FontAwesomeIcon icon="user" style={{ marginRight: 4 }} />{a.recruiter}
                  </div>
                  {a.target && (
                    <div style={{ fontSize: '0.75rem', color: 'var(--text-gray)', marginTop: '0.2rem', fontStyle: 'italic' }}>
                      {a.target}
                    </div>
                  )}
                  <div style={{ fontSize: '0.72rem', color: 'var(--text-light)', marginTop: '0.25rem', marginBottom: '0.5rem' }}>
                    <FontAwesomeIcon icon="clock" style={{ marginRight: 4 }} />{a.time}
                  </div>
                  <div style={{ display: 'flex', gap: '0.4rem' }}>
                    <button onClick={() => handleApproveAction(a.id, true)} className="btn btn-primary btn-sm">
                      <FontAwesomeIcon icon="check" style={{ marginRight: 4 }} />Approve
                    </button>
                    <button onClick={() => handleApproveAction(a.id, false)} className="btn btn-outline-secondary btn-sm">
                      <FontAwesomeIcon icon="xmark" style={{ marginRight: 4 }} />Reject
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </CompanyLayout>
  );
};

export default CompanyDashboard;
