import React, { useState, useEffect, useMemo } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import RecruiterLayout from '../components/RecruiterLayout';
import { reportService, jobService, rankingService } from '../services/supabaseService';
import { useUser } from '../context/UserContext';

const ranges = [
  { v: 'all', label: 'All Candidates' },
  { v: 'top-5', label: 'Top 5' },
  { v: 'top-10', label: 'Top 10' },
  { v: 'top-20', label: 'Top 20' },
  { v: 'top-50', label: 'Top 50' },
  { v: 'shortlist', label: 'Shortlist Only' },
];

const RecruiterReports = () => {
  const { user } = useUser();
  const [jobs, setJobs] = useState([]);
  const [reports, setReports] = useState([]);
  const [rankings, setRankings] = useState([]);
  const [form, setForm] = useState({ jobId: '', range: 'top-20', format: 'PDF' });
  const [generating, setGenerating] = useState(false);
  const [justCreated, setJustCreated] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        if (!user) return;
        const companyId = user?.company_id || user?.id;
        const j = await jobService.getJobs(companyId, user?.id).catch(() => []);
        setJobs(j || []);
        if (j && j.length) {
          const firstJobId = j[0].id;
          setForm(f => ({ ...f, jobId: firstJobId }));
          let r = await rankingService.getRankings(firstJobId).catch(() => []);
          if (!r || !r.length) {
            try {
              await rankingService.rankNow(firstJobId, companyId, user?.id);
              r = await rankingService.getRankings(firstJobId).catch(() => []);
            } catch (_) {}
          }
          setRankings(r || []);
        }
        const savedReports = await reportService.getReports().catch(() => []);
        setReports(savedReports || []);
      } finally {
        setLoading(false);
      }
    };
    if (user) load();
  }, [user]);

  useEffect(() => {
    if (!form.jobId || !user) return;
    const fetchRankings = async () => {
      const companyId = user?.company_id || user?.id;
      let r = await rankingService.getRankings(form.jobId).catch(() => []);
      if (!r || !r.length) {
        try {
          await rankingService.rankNow(form.jobId, companyId, user?.id);
          r = await rankingService.getRankings(form.jobId).catch(() => []);
        } catch (_) {}
      }
      setRankings(r || []);
    };
    fetchRankings();
  }, [form.jobId, user]);

  const sortedRankings = useMemo(() => {
    return [...rankings].sort((a, b) => (b.overall_score || b.total_score || 0) - (a.overall_score || a.total_score || 0));
  }, [rankings]);

  const samplePreviewRows = useMemo(() => {
    const count = Math.min(8, sortedRankings.length);
    return sortedRankings.slice(0, count).map((r, i) => {
      const c = r.candidates || {};
      const score = r.overall_score || r.total_score || 0.85;
      const sem = r.similarity_score || r.semantic_similarity || 0.88;
      const sk = r.skill_match_score || r.skill_match || 0.82;
      return [
        String(i + 1),
        c.name || r.candidate_name || 'Candidate Profile',
        `${Math.round(score * 100).toFixed(1)}%`,
        `${Math.round(sem * 100).toFixed(1)}%`,
        `${Math.round(sk * 100).toFixed(1)}%`,
        String(c.years_experience ?? r.years_experience ?? '3'),
      ];
    });
  }, [sortedRankings]);

  const selectedJobTitle = jobs.find(j => j.id === form.jobId)?.title || 'Untitled Role';
  const candidateCount = jobs.find(j => j.id === form.jobId)?.candidate_count || sortedRankings.length;

  const generate = async () => {
    if (!form.jobId) return;
    setGenerating(true); setJustCreated(null);
    try {
      const r = await reportService.generateReport({ jobId: form.jobId, range: form.range, format: form.format, jobTitle: selectedJobTitle });
      const rangeLabel = form.range === 'all' ? 'All' : form.range.replace('-', ' ').replace(/\b\w/g, c => c.toUpperCase());
      const fileSize = r?.file_size || `${(sortedRankings.length * 1.2).toFixed(1)} KB`;
      const entry = {
        id: r?.id || `r-${Date.now()}`,
        job_title: selectedJobTitle,
        range: rangeLabel,
        format: form.format,
        date: new Date().toISOString().slice(0, 10),
        size: fileSize,
        url: r?.url || r?.blobUrl || null,
      };
      setReports(rs => [entry, ...rs]);
      setJustCreated(entry);
    } finally { setGenerating(false); }
  };

  return (
    <RecruiterLayout
      user={user}
      title="Reports"
      subtitle="Generate and download ranking reports for stakeholders"
    >
      <div className="grid-2-1 mb-5">
        <div>
          <div className="card">
            <div className="card-header"><FontAwesomeIcon icon="pencil" style={{ marginRight: 6 }} />Generate New Report</div>
            <div className="card-body">
              <div className="grid-2 mb-3" style={{ gap: '0.8rem' }}>
                <div>
                  <label className="form-label">Job Description</label>
                  <select value={form.jobId} onChange={e => setForm({ ...form, jobId: e.target.value })} disabled={loading}>
                    <option value="">Select a job…</option>
                    {jobs.map(j => <option key={j.id} value={j.id}>{j.title} ({j.candidate_count ?? 0} candidates)</option>)}
                  </select>
                </div>
                <div>
                  <label className="form-label">Candidate Range</label>
                  <select value={form.range} onChange={e => setForm({ ...form, range: e.target.value })}>
                    {ranges.map(r => <option key={r.v} value={r.v}>{r.label}</option>)}
                  </select>
                </div>
              </div>

              <div className="mb-4">
                <label className="form-label">Format</label>
                <div className="grid-2" style={{ gap: '0.6rem', gridTemplateColumns: 'repeat(2, 1fr)' }}>
                  {[
                    { v: 'PDF', icon: <FontAwesomeIcon icon="file-pdf" />, desc: 'Stakeholder-ready PDF with branding' },
                    { v: 'Excel', icon: <FontAwesomeIcon icon="chart-bar" />, desc: 'Excel .xlsx with raw ranking data' },
                  ].map(opt => (
                    <label key={opt.v} style={{
                      display: 'flex', alignItems: 'center', gap: '0.65rem', padding: '0.8rem 0.9rem',
                      border: form.format === opt.v ? '2px solid var(--primary-mid)' : '1.5px solid var(--border-color)',
                      background: form.format === opt.v ? 'var(--primary-50)' : '#fff',
                      borderRadius: 12, cursor: 'pointer', transition: 'all 0.2s',
                    }}
                      onClick={() => setForm({ ...form, format: opt.v })}
                    >
                      <input type="radio" name="format" checked={form.format === opt.v} onChange={() => setForm({ ...form, format: opt.v })} className="form-check-input" />
                      <div style={{ fontSize: '1.35rem' }}>{opt.icon}</div>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontWeight: 700, color: 'var(--primary-dark)', fontSize: '0.88rem' }}>{opt.v}</div>
                        <div style={{ fontSize: '0.75rem', color: 'var(--text-light)' }}>{opt.desc}</div>
                      </div>
                    </label>
                  ))}
                </div>
              </div>

              <button
                className="btn btn-gold btn-lg w-100"
                onClick={generate}
                disabled={generating || !form.jobId}
              >
                {generating ? <><span className="spinner spinner-sm spinner-gold"></span> Building report…</> : <><FontAwesomeIcon icon="chart-line" style={{ marginRight: 6 }} />Generate Report</>}
              </button>

              {justCreated && (
                <div className="alert alert-success mt-3" style={{ marginBottom: 0, fontSize: '0.85rem' }}>
                  <FontAwesomeIcon icon="check" style={{ marginRight: 6 }} />{justCreated.format} report generated successfully ({justCreated.size}).
                  {justCreated.url ? (
                    <a href={justCreated.url} download target="_blank" rel="noreferrer" style={{ marginLeft: 8, fontWeight: 700, color: 'inherit' }}>Download now →</a>
                  ) : (
                    <button type="button" onClick={e => e.preventDefault()} style={{ marginLeft: 8, fontWeight: 700, background: 'transparent', border: 'none', color: 'inherit', cursor: 'pointer', padding: 0 }}>Download now →</button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="card mt-5">
            <div className="card-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span><FontAwesomeIcon icon="eye" style={{ marginRight: 6 }} />Report Preview — {selectedJobTitle}</span>
              <span className="badge badge-info">{form.format} · {ranges.find(r => r.v === form.range)?.label || 'Range'} · Live</span>
            </div>
            <div style={{ padding: '1.5rem', background: 'linear-gradient(180deg, #fff 0%, #f8f9ff 100%)' }}>
              <div style={{ textAlign: 'center', borderBottom: '3px double var(--primary-dark)', paddingBottom: '1rem', marginBottom: '1rem' }}>
                <div style={{ fontFamily: 'var(--font-display)', fontSize: '1.35rem', fontWeight: 800, color: 'var(--primary-dark)' }}>QUICK HIRE · Candidate Ranking Report</div>
                <div style={{ fontSize: '0.78rem', color: 'var(--text-light)', letterSpacing: '0.08em', textTransform: 'uppercase', marginTop: '0.25rem' }}>
                  {user?.company?.name || 'University of Limpopo'} · Group 19 · AI Recruitment Lab
                </div>
              </div>
              <div className="grid-2 mb-3" style={{ gap: '0.75rem 1.5rem', fontSize: '0.8rem' }}>
                <div><strong>Job Title:</strong> {selectedJobTitle}</div>
                <div><strong>Report Date:</strong> {new Date().toLocaleDateString()}</div>
                <div><strong>Candidates Evaluated:</strong> {candidateCount}</div>
                <div><strong>Shortlisted:</strong> {ranges.find(r => r.v === form.range)?.label || 'All'}</div>
              </div>
              <table style={{ width: '100%', fontSize: '0.78rem', borderCollapse: 'collapse' }}>
                <thead>
                  <tr style={{ background: 'var(--primary-50)' }}>
                    <th style={{ padding: '0.4rem 0.6rem', textAlign: 'left', borderBottom: '1.5px solid var(--primary-mid)' }}>Rank</th>
                    <th style={{ padding: '0.4rem 0.6rem', textAlign: 'left', borderBottom: '1.5px solid var(--primary-mid)' }}>Candidate</th>
                    <th style={{ padding: '0.4rem 0.6rem', textAlign: 'left', borderBottom: '1.5px solid var(--primary-mid)' }}>Match</th>
                    <th style={{ padding: '0.4rem 0.6rem', textAlign: 'left', borderBottom: '1.5px solid var(--primary-mid)' }}>Semantic</th>
                    <th style={{ padding: '0.4rem 0.6rem', textAlign: 'left', borderBottom: '1.5px solid var(--primary-mid)' }}>Skills</th>
                    <th style={{ padding: '0.4rem 0.6rem', textAlign: 'left', borderBottom: '1.5px solid var(--primary-mid)' }}>Yrs Exp</th>
                  </tr>
                </thead>
                <tbody>
                  {samplePreviewRows.length === 0 ? (
                    <tr>
                      <td colSpan={6} style={{ padding: '1rem', textAlign: 'center', color: 'var(--text-light)' }}>
                        No ranking data yet. Upload a job and CVs to generate rankings.
                      </td>
                    </tr>
                  ) : samplePreviewRows.map(row => (
                    <tr key={row[1]} style={{ borderBottom: '1px solid var(--border-color)' }}>
                      {row.map((cell, i) => (
                        <td key={i} style={{ padding: '0.35rem 0.6rem', color: i === 0 ? 'var(--gold-dark)' : 'var(--text-dark)', fontWeight: i === 0 ? 800 : 400 }}>
                          {cell}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
              <div style={{ fontSize: '0.72rem', color: 'var(--text-light)', marginTop: '1rem', paddingTop: '0.75rem', borderTop: '1px dashed var(--border-color)' }}>
                <em>CONFIDENTIAL — For internal use only. Generated by QUICK HIRE semantic-v3.2 model. Ranking formula: score = 0.6 × BGE similarity + 0.4 × skill match.</em>
              </div>
            </div>
          </div>
        </div>

        <div>
          <div className="card">
            <div className="card-header" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <span><FontAwesomeIcon icon="book-open" style={{ marginRight: 6 }} />Recent Reports</span>
              <span className="badge badge-primary">{reports.length}</span>
            </div>
            <div className="card-body" style={{ padding: '0.5rem' }}>
              {reports.length === 0 ? (
                <div style={{ padding: '1.25rem 1rem', color: 'var(--text-light)', fontSize: '0.85rem', textAlign: 'center' }}>
                  No reports yet. Configure options and click "Generate Report" to create your first one.
                </div>
              ) : reports.map(r => (
                <div key={r.id} style={{
                  padding: '0.75rem 0.85rem', borderRadius: 10,
                  border: '1px solid var(--border-color)', marginBottom: '0.45rem',
                  transition: 'all 0.2s',
                }}
                  onMouseEnter={e => e.currentTarget.style.cssText += ';border-color:var(--primary-light);background:var(--primary-50);'}
                  onMouseLeave={e => e.currentTarget.style.cssText += ';border-color:var(--border-color);background:#fff;'}
                >
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: '0.5rem' }}>
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div style={{ fontWeight: 700, fontSize: '0.86rem', color: 'var(--primary-dark)', marginBottom: '0.1rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                        {r.job_title}
                      </div>
                      <div style={{ fontSize: '0.75rem', color: 'var(--text-light)', display: 'flex', flexWrap: 'wrap', gap: '0.25rem 0.5rem', marginTop: '0.25rem' }}>
                        <span><FontAwesomeIcon icon="calendar-days" style={{ marginRight: 6 }} />{r.date}</span>
                        <span><FontAwesomeIcon icon="bullseye" style={{ marginRight: 6 }} />{r.range}</span>
                        <span><FontAwesomeIcon icon="box" style={{ marginRight: 6 }} />{r.size}</span>
                      </div>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '0.3rem', flexShrink: 0 }}>
                      <span className={`badge ${r.format === 'PDF' ? 'badge-error' : 'badge-success'}`}>{r.format}</span>
                      {r.url ? (
                        <a href={r.url} download target="_blank" rel="noreferrer" className="btn btn-sm btn-outline-primary" style={{ padding: '0.22rem 0.55rem', fontSize: '0.7rem', textDecoration: 'none' }}>
                          <FontAwesomeIcon icon="download" style={{ marginRight: 6 }} />DL
                        </a>
                      ) : (
                        <button className="btn btn-sm btn-outline-primary" style={{ padding: '0.22rem 0.55rem', fontSize: '0.7rem' }}>
                          <FontAwesomeIcon icon="download" style={{ marginRight: 6 }} />DL
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </RecruiterLayout>
  );
};

export default RecruiterReports;
